import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import Home from "./pages/Home";
import LoginPage from "./pages/LoginPage";
import StudentRegister from "./pages/StudentRegister";
import TutorRegister from "./pages/TutorRegister";
import StudentDashboard from "./pages/StudentDashboard";
import TutorDashboard from "./pages/TutorDashboard";
import MatchView from "./pages/MatchView";
import Navbar from "./components/Navbar";
import AddRoleRoute from "./components/AddRoleRoute";
import ProtectedRoute from "./components/ProtectedRoute";

function App() {
  return (
    <Router>
      <Navbar />
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/login" element={<LoginPage />} />
        <Route path="/student/register" element={<StudentRegister />} />
        <Route path="/tutor/register" element={<TutorRegister />} />
        <Route path="/match" element={<ProtectedRoute><MatchView /></ProtectedRoute>} />
        <Route path="/student/dashboard" element={<AddRoleRoute role="student"><StudentDashboard /></AddRoleRoute>} />
        <Route path="/tutor/dashboard" element={<AddRoleRoute role="tutor"><TutorDashboard /></AddRoleRoute>} />
      </Routes>
    </Router>
  );
}

export default App;
